<script setup lang="ts">import {imageUrl} from '../lib/pages';import type {MediaAsset} from '../lib/media';defineProps<{modelValue?:string;label:string;media:MediaAsset[];site?:string}>();defineEmits<{(e:'update:modelValue',value:string):void}>();const builtins=[['/assets/redesign/agl-hero.webp','Мир AGL'],['/assets/redesign/agl-hero-mobile.webp','Мир AGL · телефон'],['/assets/redesign/rublemet-cover.webp','Рублемёт'],['/assets/redesign/personal-studio.webp','Портфолио'],['/assets/alexey-portrait.webp','Портрет'],['/assets/rublemet-street.webp','Город Рублемёта'],['/assets/rublemet-character.webp','Герой Рублемёта']];</script><template><label>{{label}}<select :value="modelValue" @change="$emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="">Без изображения</option><optgroup label="Материалы сайта"><option v-for="[src,name] in builtins.filter(x=>site==='personal'?!x[0].includes('agl-hero')&&!x[0].includes('rublemet-street')&&!x[0].includes('rublemet-character'):!x[0].includes('personal-studio'))" :key="src" :value="src">{{name}}</option></optgroup><optgroup label="Медиатека"><option v-for="item in media" :key="item.id" :value="'media:'+item.id">{{item.title}}</option></optgroup></select></label></template>
